DELETE FROM puntuaciones WHERE categoria='castillos';
DELETE FROM entidades WHERE fuente='inventario_castillos_pdf';

INSERT OR IGNORE INTO puntuaciones (codigo_ine, categoria, puntuacion)
SELECT codigo_ine, 'castillos', 30 FROM municipios;

-- 11 municipios con 100 puntos
UPDATE puntuaciones SET puntuacion=100 WHERE codigo_ine IN (SELECT codigo_ine FROM municipios WHERE (UPPER(TRIM(nombre))='ALMERÍA' AND UPPER(TRIM(provincia))='ALMERÍA') OR (UPPER(TRIM(nombre))='GRANADA' AND UPPER(TRIM(provincia))='GRANADA') OR (UPPER(TRIM(nombre))='SEVILLA' AND UPPER(TRIM(provincia))='SEVILLA') OR (UPPER(TRIM(nombre))='LOARRE' AND UPPER(TRIM(provincia))='HUESCA') OR (UPPER(TRIM(nombre))='SEGOVIA' AND UPPER(TRIM(provincia))='SEGOVIA') OR (UPPER(TRIM(nombre))='GORMAZ' AND UPPER(TRIM(provincia))='SORIA') OR (UPPER(TRIM(nombre))='MEDINA DEL CAMPO' AND UPPER(TRIM(provincia))='VALLADOLID') OR (UPPER(TRIM(nombre))='ÁVILA' AND UPPER(TRIM(provincia))='ÁVILA') OR (UPPER(TRIM(nombre))='FIGUERES' AND UPPER(TRIM(provincia))='GIRONA') OR (UPPER(TRIM(nombre))='PALMA' AND UPPER(TRIM(provincia))='BALEARES') OR (UPPER(TRIM(nombre))='PALMA' AND UPPER(TRIM(provincia))='BALEARES')) AND categoria='castillos';

